      "topic": {
        "text": "Logical AND operator (&&) in Java",
        "refs": ["Q0000", "Q0001"]
      },
      "explanation_text": {
        "text": "The && operator evaluates the left-hand condition first; if it is false, Java short‑circuits and does not evaluate the right-hand condition, because the overall expression cannot be true. The result is true only when both conditions are true.",
        "refs": ["Q0000", "Q0001"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Logical OR operator (||) in Java",
        "refs": ["Q0002", "Q0003", "Q0004"]
      },
      "explanation_text": {
        "text": "The || operator evaluates the left-hand condition first; if it is true, Java short‑circuits and does not evaluate the right-hand condition, because the overall expression is already true. The result is true when at least one of the conditions is true.",
        "refs": ["Q0002", "Q0003", "Q0004"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Logical NOT operator (!) in Java",
        "refs": ["Q0005"]
      },
      "explanation_text": {
        "text": "The ! operator reverses the boolean value of its operand: true becomes false and false becomes true.",
        "refs": ["Q0005"]
      },
      "explanation_type": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "AND operator with temperature range",
        "refs": ["Q0000", "Q0001"]
      },
      "example_text": {
        "text": "int temperature = 22; boolean isWarm = temperature > 20 && temperature < 30; // isWarm is true. If temperature is 12, isWarm becomes false.",
        "refs": ["Q0000", "Q0001"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "OR operator with loan eligibility",
        "refs": ["Q0002", "Q0003", "Q0004"]
      },
      "example_text": {
        "text": "boolean hasHighIncome = true; boolean hasGoodCredit = true; boolean isEligible = hasHighIncome || hasGoodCredit; // isEligible is true because at least one condition is true.",
        "refs": ["Q0002", "Q0003", "Q0004"]
      },
      "example_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "The && operator returns true only when both operands are true; otherwise it returns false.",
        "refs": ["Q0000", "Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The || operator returns true when at least one operand is true; it returns false only when both operands are false.",
        "refs": ["Q0002", "Q0003", "Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The ! operator inverts a boolean value.",
        "refs": ["Q0005"]
      },
      "fact_type": null
    }
  ],
